diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..ba438c5
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,98 @@
+// Importing till sales from CSV (ticket,soldAt,dishId,qty).
+// Each dish sold uses one portion of its recipe per qty, consuming ingredients
+// with ref "sale:<ticket>". Tickets already imported are skipped; any invalid
+// row or stock shortage rejects the whole file without changing the store.
+import { AppError } from "../errors.js";
+import { isDate } from "../dates.js";
+import { consume } from "../domain/batches.js";
+import { getItem, onHand } from "../domain/items.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { parseCsv } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+const ISO_INSTANT = /^\d{4}-\d{2}-\d{2}T([01]\d|2[0-3]):[0-5]\d(:[0-5]\d(\.\d+)?)?(Z|[+-]([01]\d|2[0-3]):[0-5]\d)$/;
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+function parseIsoInstant(value) {
+  if (typeof value !== "string" || !ISO_INSTANT.test(value) || !isDate(value.slice(0, 10))) return null;
+  const ms = Date.parse(value);
+  return Number.isFinite(ms) ? new Date(ms).toISOString() : null;
+}
+
+/** Imports till sales; returns { tickets, dishes } counts or throws naming the row. */
+export function importSales(store, text) {
+  const table = parseCsv(text);
+  if (!table.length) return { tickets: 0, dishes: 0 };
+  const [head, ...dataRows] = table;
+  const keys = head.map((h) => h.trim());
+  for (const k of HEADER) {
+    if (!keys.includes(k)) throw new AppError("bad_request", { reason: `missing column ${k}` });
+  }
+  const rows = dataRows.map((r) => Object.fromEntries(keys.map((k, i) => [k, (r[i] ?? "").trim()])));
+
+  const clean = rows.map((r, i) => {
+    const where = `row ${i + 2}`;
+    if (!r.ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    const soldAt = parseIsoInstant(r.soldAt);
+    if (!soldAt) throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    const dishId = Number(r.dishId);
+    if (!r.dishId || !Number.isInteger(dishId) || dishId < 1)
+      throw new AppError("bad_request", { reason: `${where}: bad dishId` });
+    const dish = (store.data.dishes ?? []).find((d) => d.id === dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `${where}: unknown dish ${dishId}` });
+    const recipe = store.data.recipes.find((rec) => rec.id === dish.recipeId);
+    if (!recipe) throw new AppError("bad_request", { reason: `${where}: unknown recipe ${dish.recipeId}` });
+    const qty = Number(r.qty);
+    if (!r.qty || !Number.isInteger(qty) || qty < 1)
+      throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    return { where, ticket: r.ticket, soldAt, dishId, qty, recipeId: dish.recipeId };
+  });
+
+  const imported = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const pending = clean.filter((row) => !imported.has(row.ticket));
+  if (!pending.length) return { tickets: 0, dishes: 0 };
+
+  const stock = new Map();
+  const availableOf = (itemId) => {
+    if (!stock.has(itemId)) stock.set(itemId, onHand(store, itemId));
+    return stock.get(itemId);
+  };
+
+  for (const row of pending) {
+    for (const n of scaled(getRecipe(store, row.recipeId), row.qty)) {
+      if (n.qty <= 0) continue;
+      const avail = availableOf(n.itemId);
+      if (avail < n.qty) {
+        const item = getItem(store, n.itemId);
+        throw new AppError("sales_not_enough_stock", {
+          where: row.where,
+          item: item.name,
+          available: round3(avail),
+          unit: item.unit,
+        });
+      }
+      stock.set(n.itemId, round3(avail - n.qty));
+    }
+  }
+
+  store.data.sales ??= [];
+  const tickets = new Set();
+  let dishes = 0;
+  for (const row of pending) {
+    for (const n of scaled(getRecipe(store, row.recipeId), row.qty)) {
+      if (n.qty > 0) consume(store, n.itemId, n.qty, { at: row.soldAt, ref: `sale:${row.ticket}` });
+    }
+    store.data.sales.push({
+      id: store.nextId("sale"),
+      ticket: row.ticket,
+      soldAt: row.soldAt,
+      dishId: row.dishId,
+      qty: row.qty,
+    });
+    tickets.add(row.ticket);
+    dishes += row.qty;
+  }
+
+  return { tickets: tickets.size, dishes };
+}
